/**
 * @fileoverview A package that passes a callback on to another package, through frames of its own.
 * @module frame-relay
 */
import { descend } from "callback-walker";

/**
 * Hand `callback` to `callback-walker` from `depth` frames of this function.
 * @param {number} depth - How deep to recurse here, and again in `callback-walker`.
 * @param {function(): *} callback - What to call.
 * @returns {*} What the callback returned.
 * @example
 * relay(3, () => 1); // 1
 */
export function relay(depth, callback) {
	return depth > 0 ? relay(depth - 1, callback) : descend(depth, callback);
}
